PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://example.com/ref#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?point ?ts ?label ?pname
WHERE {
  ?point brick:hasSubclass* ?class .
  optional {}
}
LIMIT 1

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?zone WHERE {
  ?zone rdf:type brick:Zone .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?point ?class WHERE {
  ?point rdf:type brick:AirTemperature .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?class WHERE {
  ?point rdf:type ?class .
  FILTER(str(?class) LIKE "%Temperature%")
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?class WHERE {
  ?point rdf:type ?class .
  FILTER(str(?class) LIKE "%Temperature%")
}

